        if not isinstance(metadata, dict):
            return jsonify({"error": "Bad request"}), 400
        current_todo['metadata'] = metadata

    current_todo['version'] += 1
    current_todo['updated_at'] = updated_at_ts
    team_data['todos'][todo_id] = current_todo

