        return jsonify({"error": "Unauthorized", "message": "Missing or invalid X-Team-ID header"}), 401

    team_data = teams[x_team_id]
    todos = list(team_data['todos'].values())

    # Parse page
    page_str = request.args.get('page')
    try:
        page = int(page_str) if page_str else 1
        if page <= 0:
            return jsonify({"error": "Bad request"}), 400
    except:
        return jsonify({"error": "Bad request"}), 400

    # Parse sort
    sort = request.args.get('sort', 'created_asc')
    valid_sorts = ['created_asc', 'created_desc', 'title']
    if sort not in valid_sorts:
        return jsonify({"error": "Bad request"}), 400

    # Parse completed filter
    completed_filter = request.args.get('completed')
    if completed_filter is not None:
        try:
            is_completed = completed_filter.lower() == 'true'
            todos = [t for t in todos if t.get('completed') == is_completed]
        except:
            return jsonify({"error": "Bad request"}), 400

    # Parse tag filter
    tag_filter = request.args.get('tag')
    if tag_filter is not None:
        tag = str(tag_filter)
        todos = [t for t in todos if tag in t.get('tags', [])]

    # Sort
    if sort == 'created_asc':
        todos.sort(key=lambda t: t.get('created_at', ''))
    elif sort == 'created_desc':
        todos.sort(key=lambda t: t.get('created_at', ''), reverse=True)
    elif sort == 'title':
        todos.sort(key=lambda t: t.get('title', ''))

    # Pagination
    page_size = 50
    start = (page - 1) * page_size
    end = start + page_size
    paginated = todos[start:end]
    total = len(todos)
    next_cursor = page + 1 if end < total else None

    return jsonify({
        "todos": paginated,
        "page": page,
        "page_size": page_size,
        "next_cursor": next_cursor,
        "total": total
    }), 200

