    if not isinstance(data, dict):
        return jsonify({"error": "Bad request"}), 400

    if 'updates' not in data:
        return jsonify({"error": "Bad request"}), 400

    updates = data['updates']
    if not isinstance(updates, list):
        return jsonify({"error": "Bad request"}), 400

    if len(updates) > 100:
        return jsonify({"error": "Bad request"}), 400

    team_data = teams[x_team_id]

    # Check structure of each update item
    struct_valid = True
    for update in updates:
        if not isinstance(update, dict):
            struct_valid = False
            break
        if 'id' not in update:
            struct_valid = False
            break

    if not struct_valid:
        return jsonify({"error": "Bad request"}), 400

    # Check existence and content validity
    exists_valid = True
    content_valid = True

    for update in updates:
        todo_id = update['id']
        if todo_id not in team_data['todos']:
            exists_valid = False
            break

        # Validate content
        if 'title' in update:
            title = update['title']
            title_str = str(title)
            if not title_str or title_str.strip() == "":
                content_valid = False
                break
            if len(title_str) > 1000:
                content_valid = False
                break
            title_lower = title_str.lower()
            if "drop table" in title_lower or "select *" in title_lower or "union select" in title_lower:
                content_valid = False
                break
            if "or 1=1" in title_lower or "or '1'='1" in title_lower:
                content_valid = False
                break
        if 'completed' in update:
            if not isinstance(update['completed'], bool):
                content_valid = False
                break
        if 'tags' in update:
            tags = update['tags']
            if not isinstance(tags, list):
                content_valid = False
                break
            for tag in tags:
                if not isinstance(tag, str):
                    content_valid = False
                    break
                if len(tag) > 100:
                    content_valid = False
                    break
        if 'metadata' in update:
            metadata = update['metadata']
            if not isinstance(metadata, dict):
                content_valid = False
                break

    if not exists_valid:
        return jsonify({"error": "Todo not found"}), 404

    if not content_valid:
        return jsonify({"error": "Bad request"}), 400

    # All valid - apply updates atomically
    updated_list = []
    with todos_lock:
        team_data = teams[x_team_id]
        for update in updates:
            todo_id = update['id']
            todo = team_data['todos'][todo_id]
            # Update fields
            if 'title' in update:
                todo['title'] = update['title']
            if 'completed' in update:
                todo['completed'] = update['completed']
            if 'tags' in update:
                todo['tags'] = update['tags']
            if 'metadata' in update:
                todo['metadata'] = update['metadata']
            todo['version'] += 1
            todo['updated_at'] = get_iso_now()

            # Prepare response object
            updated_todo = {
                "id": todo['id'],
                "title": todo['title'],
                "team_id": todo['team_id'],
                "completed": todo['completed'],
                "version": todo['version'],
                "created_at": todo['created_at'],
                "updated_at": todo['updated_at'],
                "tags": todo['tags'],
                "metadata": todo['metadata']
            }
            updated_list.append(updated_todo)

        # Update the actual stored todos (already done above with direct mutation)
        # Actually we modified team_data['todos'][todo_id] directly in the loop above
        # But we need to make sure the team_data object is updated outside the lock?
        # The lock covers reading and writing. We're modifying team_data['todos'][todo_id] directly.
        # That should be fine as long as we hold the lock.

    return jsonify({
        "updated": updated_list,
        "count": len(updates)
    }), 200

# ============== Export ==============

@app.route('/todos/export', methods=['GET'])
