# ============== Rate Limiting Middleware ==============
@app.after_request
def apply_rate_limit(response):
    # Check rate limit for team that made request (except /teams POST)
    team_id = request.headers.get('X-Team-ID')
    if team_id and team_id in teams:
        allowed, _ = check_rate_limit(team_id)
        if not allowed:
            return jsonify({"error": "Rate limit exceeded", "retry_after": 60}), 429
    return response
