todos_lock = threading.Lock()

rate_limits: Dict[str, list] = defaultdict(list)  # team_id -> list of timestamps
rate_limit_lock = threading.Lock()
RATE_LIMIT = 100

def get_iso_now() -> str:
    return datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")

def check_rate_limit(team_id: str) -> bool:
    """Check if team is under rate limit. Returns True if allowed to proceed, False if blocked."""
    with rate_limit_lock:
        now = datetime.now(timezone.utc)
        cutoff = now.timestamp() - 60
        rate_limits[team_id] = [ts for ts in rate_limits[team_id] if ts > cutoff]
        if len(rate_limits[team_id]) >= RATE_LIMIT:
            return False  # already at limit
        rate_limits[team_id].append(now.timestamp())
